- VAR history : ARRAY[0..99] OF LREAL; historyCount : INT; writeIndex : INT; lastWindowSize : INT := 0; sum maybe.
- On accepted sample:
  - if historyCount < windowSize:
    history[writeIndex] := value; writeIndex := writeIndex+1 (mod 100? If count < windowSize <=100, writeIndex starts 0 and <100; no need mod but after window changes reset writeIndex)
    historyCount +=1
